void Solver::rephase() {
    // 1) Reset the rephase counter – we start a fresh rephase cycle.
    rephases = 0;

    // 2) Adjust the trail‑size threshold.
    //    Instead of shrinking it, we raise it a little so that the next
    //    rephase will happen after a larger amount of search effort.
    //    Use the current trail length as a lower bound.
    threshold = std::max((int)trail.size(), (int)(threshold * 1.10));

    // 3) Grow the rephase limit adaptively.
    //    The more conflicts we have seen, the larger the limit becomes,
    //    allowing the solver to stay longer in the current phase before
    //    forcing another rephase.
    rephase_limit += (conflicts / 10) + 1000;

    // 4) Update the saved phase information.
    //    We keep a mixture of deterministic and random strategies:
    //      • 70 % of the time we copy the best local phase seen so far.
    //      • 20 % of the time we invert that best phase (to escape local minima).
    //      • 10 % of the time we pick a completely random polarity.
    int r = rand() % 100;
    if (r < 70) {
        // copy the locally best phase
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 90) {
        // invert the locally best phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // random polarity
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}

