void Solver::rephase() {
    // 1) Reset the rephase counter – we start a fresh re‑phase cycle.
    rephases = 0;

    // 2) Make the next re‑phase trigger a bit earlier.
    //    Instead of a simple 0.9 factor we use a slightly stronger reduction
    //    and also ensure the threshold never drops below a small constant.
    threshold = std::max( (int)(threshold * 0.85), 100 );

    // 3) Grow the re‑phase limit, but keep it bounded to avoid runaway growth.
    //    The original code added a fixed 8192; we add a smaller step and cap it.
    const int REPHASE_LIMIT_MAX = 200000;
    rephase_limit = std::min( rephase_limit + 4096, REPHASE_LIMIT_MAX );

    // 4) Refresh the saved phase information.
    //    Use the best phase seen so far (local_best) but occasionally flip it
    //    to inject diversification. This helps the solver escape from a bad
    //    polarity bias after many restarts.
    for (int v = 1; v <= vars; ++v) {
        if (local_best[v] != 0) {
            // 50 % chance to keep the best polarity, otherwise invert it.
            saved[v] = (rand() & 1) ? local_best[v] : -local_best[v];
        } else {
            // If we have never seen a value for this variable, pick a random polarity.
            saved[v] = (rand() & 1) ? 1 : -1;
        }
    }
}
